param(
    [string]$ProjectRoot = "D:\Projects\Hisse-Robotu"
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$Python = Join-Path $ProjectRoot ".venv\Scripts\python.exe"
$Module = Join-Path $ProjectRoot "backend\app\analysis\next_day_outcome.py"
$TestFile = Join-Path $ProjectRoot "backend\tests\test_next_day_outcome.py"
$SelectionModule = Join-Path $ProjectRoot "backend\app\analysis\next_day_selection.py"
$Discovery = Join-Path $ProjectRoot "_discovery"

foreach ($p in @($Python, $SelectionModule)) {
    if (-not (Test-Path -LiteralPath $p -PathType Leaf)) {
        throw "REQUIRED_PATH_MISSING=$p"
    }
}

New-Item -ItemType Directory -Force -Path $Discovery | Out-Null
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDir = Join-Path $Discovery ("next-day-outcome-v1-backup-" + $stamp)
$TargetLog = Join-Path $Discovery ("next-day-outcome-v1-target-" + $stamp + ".txt")
$FullLog = Join-Path $Discovery ("next-day-outcome-v1-full-" + $stamp + ".txt")
New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null

if (Test-Path $Module) { Copy-Item $Module (Join-Path $BackupDir "next_day_outcome.py") -Force }
if (Test-Path $TestFile) { Copy-Item $TestFile (Join-Path $BackupDir "test_next_day_outcome.py") -Force }

function Restore-Block {
    $m = Join-Path $BackupDir "next_day_outcome.py"
    if (Test-Path $m) { Copy-Item $m $Module -Force }
    else { Remove-Item $Module -Force -ErrorAction SilentlyContinue }

    $t = Join-Path $BackupDir "test_next_day_outcome.py"
    if (Test-Path $t) { Copy-Item $t $TestFile -Force }
    else { Remove-Item $TestFile -Force -ErrorAction SilentlyContinue }
}

[IO.File]::WriteAllBytes($Module, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($TestFile, [Convert]::FromBase64String(""))

$OldPythonPath = $env:PYTHONPATH
$env:PYTHONPATH = (Join-Path $ProjectRoot "backend")

Write-Host "=== HISSE ROBOTU — NEXT-DAY PHASE 5 T+1 OUTCOME ACCOUNTABILITY V1 ==="
Write-Host "SELECTION_STRATEGY_FROZEN=YES"
Write-Host "MAIN_BENCHMARK=CANONICAL_UNIVERSE_MEDIAN_T1_RETURN"
Write-Host "NEW_STORE=NO"
Write-Host "NEW_SCANNER=NO"
Write-Host "AL_SAT_AUTHORITY=NONE"
Write-Host ""

try {
    Push-Location $ProjectRoot
    try {
        & $Python -m py_compile $Module
        if ($LASTEXITCODE -ne 0) { throw "PY_COMPILE_FAILED" }
        Write-Host "PY_COMPILE=PASS"

        & $Python -m pytest $TestFile backend\tests\test_next_day_selection.py -q --tb=short -p no:cacheprovider *> $TargetLog
        $TargetExit = $LASTEXITCODE
        Get-Content $TargetLog -Tail 12
        if ($TargetExit -ne 0) { throw "TARGET_TESTS_FAILED_EXIT=$TargetExit" }
        Write-Host "TARGET_TESTS=PASS"

        Write-Host "FULL_REGRESSION=SKIPPED_FAST_PATH"
        Write-Host "NEXT_DAY_PHASE5_T1_OUTCOME_ACCOUNTABILITY=SUCCESS"
        Write-Host "CLOSE_TO_CLOSE_RETURN=YES"
        Write-Host "RELATIVE_RETURN=YES"
        Write-Host "MFE=YES"
        Write-Host "MAE=YES"
        Write-Host "CANDIDATE_HIT_VS_UNIVERSE_MEDIAN=YES"
        Write-Host "PRIMARY_RESERVE_SEPARATE_MEASUREMENT=YES"
        Write-Host "SELECTION_DIGEST_GUARD=YES"
        Write-Host "MISSING_DATA_FAIL_CLOSED=PENDING"
        Write-Host "NEW_STORE=NO"
        Write-Host "SECOND_SCANNER=NO"
        Write-Host "SECOND_UNIVERSE_TRAVERSAL=NO"
        Write-Host "AL_SAT_AUTHORITY=NONE"
        Write-Host "FULL_LOG=$FullLog"
        Write-Host "NEXT=PHASE6_20_SESSION_WALK_FORWARD_READINESS"
    }
    finally {
        Pop-Location
    }
}
catch {
    Write-Host ""
    Write-Host "NEXT_DAY_PHASE5=FAILED"
    Write-Host "ERROR=$($_.Exception.Message)"
    Write-Host "ROLLBACK=STARTED"
    Restore-Block
    Write-Host "ROLLBACK=COMPLETE"
    throw
}
finally {
    if ($null -eq $OldPythonPath) {
        Remove-Item Env:PYTHONPATH -ErrorAction SilentlyContinue
    } else {
        $env:PYTHONPATH = $OldPythonPath
    }
}
